#!/bin/bash
# HBM-LANDING 10-18: behavioural bench of the HBM d4g forwarded-clock HALF-CYCLE lane masters + landings
# (rtl/hbm_accel/die_glue/hbfd_lane_masters.sv, generated by tools/hbm_die_v16/gen_hbm_lane_masters.py; cores
# rtl/qwen_split/qfd_fwd_lane.sv + rtl/hbm_accel/die_glue/ot_hbm_lane.sv) -- Verilator 5.050 (run it on the fleet).
# usage: hbm_lane_bench.sh <pass|sel|naive|vld|full|noinv|hop0inv|forkck> <work dir> [W in 48|136|624]
#  pass: (a) single-branch lanes NF = 1 (land0), 2, 5, 8, 27 frames, source released before / after the receiver;
#        (b) dL SWEEP: NF = 3 lanes whose landing write edge sits dL = 0 (phase wrap), T/2, T, 2T behind the nominal, each
#            also at -80 / +80 ps (scaled to this bench's T = 10 ns: +-0.96 ns) with the NOMINAL lane's K (one E covers
#            both corners): the latency must be the same;
#        (c) FORK tree: hop0 -> lh_f2 -> {lh -> landA, lh_f3 -> {landB, lh -> landC, lh -> lh(+XL) -> landD}} and a hop-0
#            fork lh0_f2 -> {landE, lh -> landF}: every landing on the receiver root;
#        (d) SLIP: a lane strapped K + D (read outside the D x T window) must raise fault (and only that lane).
#        Per landing the bench derives the latency L from the geometry, K = (L - 1 - (R0 - G)) mod 8, and checks on every
#        receiver edge: o = w(t - 1 - L) once written (0 bubbles before), fault = 0.
#        Latency (measured): the word the source launches at its edge e is at o after receiver edge e + L + 1, with
#          L = ceil(((N + 2) * T/2 + dLclk - Droot) / T + 1/4)   N >= 1 stations incl. hop 0 (hop 0 = one full root cycle,
#          each further station T/2), dLclk = the forwarded clock legs' sum, Droot = receiver root - source root;
#          i.e. 1 (hop 0) + (N - 1)/2 (stations) + 1/2 (ring write) + E (handoff, from the die STA) + 1 (o).
#          land0 lanes (N = 0, Qwen inverting gate in the landing): L = ceil((T/2 + 0 - Droot) / T + 1/4).
#        PASS line: LANE_BENCH PASS 0 errors in <checks> checks
#  sel / naive / vld / full / noinv (land0 gate non-inverting) / hop0inv (Qwen inverting hop 0) / forkck: the same bench
#        on RTL built with one mutant define -- each must FAIL.
set -u
mode=$1; O=$2; W=${3:-136}
cd "$(dirname "$0")/../.."; mkdir -p "$O"
export PATH=/home/ubuntu/.local/opentallas-tools/verilator-5.050/bin:$PATH
DEF=
case $mode in
  pass) ;; sel) DEF=+define+OT_QFD_LAND_MUT_SEL ;; naive) DEF=+define+OT_QFD_LAND_MUT_NAIVE ;;
  vld) DEF=+define+OT_QFD_LAND_MUT_VLD ;; full) DEF=+define+OT_QFD_LANE_MUT_FULL ;; noinv) DEF=+define+OT_QFD_LANE_MUT_NOINV ;; hop0inv) DEF=+define+OT_HBM_LANE_MUT_HOP0INV ;;
  forkck) DEF=+define+OT_HBM_LANE_MUT_FORKCK ;;
  *) echo "bad mode $mode"; exit 2 ;;
esac
cat > "$O/tb.sv" <<'EOT'
`timescale 1ns/1ps
module tdly #(parameter integer W = 1, parameter real D = 1.0) (input wire [W-1:0] a, output wire [W-1:0] y);
    localparam integer NS = (D <= 4.0) ? 1 : $rtoi($ceil(D / 4.0));
    wire [W-1:0] s [0:NS];
    assign s[0] = a;
    genvar i;
    generate for (i = 0; i < NS; i = i + 1) begin : g
        assign #(D / NS) s[i + 1] = s[i];
    end endgenerate
    assign y = s[NS];
endmodule
// one hop: data leg DD, clock leg CD (epoch on the data leg)
module hop #(parameter integer W = 1, parameter real CD = 3.6, DD = 1.2) (input wire [W-1:0] b, input wire eb, input wire ck,
                                                                          output wire [W-1:0] a, output wire ea, output wire ckf);
    tdly #(W, DD) u_d (b, a); tdly #(1, DD) u_e (eb, ea); tdly #(1, CD) u_c (ck, ckf);
endmodule
// landing checker: geometry -> L, K; checks o = w(ed - 1 - L)
module chk #(parameter integer W = 136, NF = 3, parameter real LAG = 0.0, DOFF = 2.0, parameter integer G = 10, R0 = 12,
             EXPF = 0, NOPH = 0) (input wire ckd, input wire [31:0] ed, input wire [W-1:0] o, input wire flt, input wire ckf,
                                  output integer err, output integer n);
    localparam real T = 10.0;
    function automatic [W-1:0] w_of(input integer e); w_of = W'(e * 40503 + (e >>> 3) + 7) ^ (W'(e) << (W - 8)); endfunction
    integer L, K, te_; reg [W-1:0] ex_; reg kset = 0;
    initial begin err = 0; n = 0;
        L = $rtoi($ceil(((NF + (NF > 1 ? 1 : 0)) * T / 2.0 + LAG - DOFF) / T + 0.25));
        K = ((L - 1 - (R0 - G)) % 8 + 8) % 8;
        $display("LANE %m NF=%0d LAG=%0.2f L=%0d K=%0d EXPF=%0d", NF, LAG, L, K, EXPF);
    end
    // write-clock phase: the landing's ckf must rise at source edge + NF x T/2 + the clock legs (source root posedges at
    // 5 + 10 e): a full-cycle forward anywhere on the path (mutants full / forkck / noinv) moves it by T/2
    real ph;
    always @(posedge ckf) if (NOPH == 0 && $realtime > 5.0 + (NF + 1) * T / 2.0 + LAG + T * G - 1.0) begin   // the lane's real (gated) edges
        ph = $realtime - 5.0 - (NF + 1) * T / 2.0 - LAG; ph = ph - T * $floor(ph / T + 0.5);
        if (ph > 0.05 || ph < -0.05) begin err = err + 1; if (err < 4) $display("LANE_PHASE %m t=%0.2f off=%0.2f", $realtime, ph); end
    end
    always @(negedge ckd) begin
        te_ = ed; te_ = te_ - 1 - L;
        ex_ = (te_ >= G) ? w_of(te_) : {W{1'b0}};
        if (ed > R0 + 12) begin
            n = n + 1;
            if (EXPF == 0 && (o !== ex_ || flt !== 1'b0)) begin
                err = err + 1;
                if (err < 4) $display("LANE_MISMATCH %m ed=%0d o=%h exp=%h fault=%b", ed, o, ex_, flt);
            end
        end
    end
endmodule
`define LH0(n)  hbfd_lh0_``n``_EW
module tb;
    localparam integer W = 136;
    localparam real T = 10.0, DOFF = 2.0;
    reg cks = 0, ckd = 0; reg [31:0] es = 0, ed = 0;
    always #5 cks = ~cks;
    initial begin #2.0; forever #5 ckd = ~ckd; end
    always @(posedge cks) es <= es + 1;
    always @(posedge ckd) ed <= ed + 1;
    function automatic [W-1:0] w_of(input integer e); w_of = W'(e * 40503 + (e >>> 3) + 7) ^ (W'(e) << (W - 8)); endfunction
    localparam integer NL = 32;
    integer e [0:NL-1], c [0:NL-1]; wire [NL-1:0] f;
    // ---------------------------------------------------------------- sources (G per group) and receiver resets
    reg [W-1:0] src = 0; reg en10 = 0, en40 = 0, en9 = 0, en12 = 0;
    always @(posedge cks) begin src <= w_of(es); en10 <= (es >= 10); en40 <= (es >= 40); en9 <= (es >= 9); en12 <= (es >= 12); end
    reg rs12 = 0, rs9 = 0, rs45 = 0, rs14 = 0, rs11 = 0;
    always @(posedge ckd) begin rs12 <= (ed >= 12); rs9 <= (ed >= 9); rs45 <= (ed >= 45); rs14 <= (ed >= 14); rs11 <= (ed >= 11); end
    // K strap of a checker (set at time 0 from its geometry; slip lanes add D)
    `define KOF(ck, add) (((ck.K + add) % 8))
    // ---------------------------------------------------------------- (a) single-branch lanes
    // lane macro: NF frames, CD, DD, last-hop extra lag XL, enable EN (G), reset RS (R0)
    `define LANE(id, NF_, CD_, DD_, XL_, EN, G_, RS, R0_, KADD, EXPF_) \
      wire [W-1:0] o_``id; wire [2:0] k_``id; wire ckl_``id; \
      chk #(.W(W), .NF(NF_), .LAG((NF_ - 1) * CD_ + XL_), .G(G_), .R0(R0_), .EXPF(EXPF_), .NOPH(NF_ == 1)) c_``id (ckd, ed, o_``id, f[id], ckl_``id, e[id], c[id]); \
      assign k_``id = `KOF(c_``id, KADD); \
      if (NF_ == 1) begin : g_``id \
        assign ckl_``id = 1'b0; \
        hbfd_land0_136_EW u_l (.ck_s(cks), .en(EN), .a(src), .ck(ckd), .rs(RS), .k0(k_``id[0]), .k1(k_``id[1]), .k2(k_``id[2]), .b(o_``id), .fault(f[id])); \
      end else begin : g_``id \
        wire [W-1:0] d [0:NF_-1]; wire ea [0:NF_-1]; wire cf [0:NF_-1]; \
        wire [W-1:0] b0; wire eb0, co0; \
        assign ckl_``id = cf[NF_ - 1]; \
        hbfd_lh0_136_EW u_s0 (.ck(cks), .en(EN), .a(src), .b(b0), .eb(eb0), .ck_o(co0)); \
        hop #(W, CD_ + (NF_ == 2 ? XL_ : 0.0), DD_ + (NF_ == 2 ? XL_ : 0.0)) u_h1 (b0, eb0, co0, d[1], ea[1], cf[1]); \
        for (genvar j = 1; j < NF_ - 1; j = j + 1) begin : g_st \
          wire [W-1:0] bj; wire ebj, coj; \
          hbfd_lh_136_EW u_s (.ckf(cf[j]), .ea(ea[j]), .a(d[j]), .b(bj), .eb(ebj), .ck_o(coj)); \
          hop #(W, CD_ + (j == NF_ - 2 ? XL_ : 0.0), DD_ + (j == NF_ - 2 ? XL_ : 0.0)) u_h (bj, ebj, coj, d[j + 1], ea[j + 1], cf[j + 1]); \
        end \
        hbfd_land_136_EW u_l (.ckf(cf[NF_ - 1]), .ea(ea[NF_ - 1]), .a(d[NF_ - 1]), .ck(ckd), .rs(RS), .k0(k_``id[0]), .k1(k_``id[1]), .k2(k_``id[2]), .b(o_``id), .fault(f[id])); \
      end
    `LANE(0,  1, 0.0, 1.2, 0.0, en10, 10, rs12, 12, 0, 0)
    `LANE(1,  2, 3.6, 1.2, 0.0, en10, 10, rs12, 12, 0, 0)
    `LANE(2,  5, 3.6, 1.2, 0.0, en10, 10, rs12, 12, 0, 0)
    `LANE(3,  5, 4.4, 1.2, 0.0, en40, 40, rs9,  9,  0, 0)
    `LANE(4,  5, 4.4, 1.2, 0.0, en9,  9,  rs45, 45, 0, 0)
    `LANE(5,  8, 4.0, 0.4, 0.0, en10, 10, rs14, 14, 0, 0)
    `LANE(6, 27, 4.5, 2.0, 0.0, en12, 12, rs11, 11, 0, 0)
    // ---------------------------------------------------------------- (b) dL sweep, NF = 3, base lag 2 x 3.6 = 7.2 -> write
    // edge at 20 + 7.2 - 2 = 25.2 ns behind the source edge (hop 0 = T); XL puts it at 30 (phase 0 wrap), 35 (T/2), 40 (T), 50 (2T)
    `LANE(7,  3, 3.6, 1.2,  4.8, en10, 10, rs12, 12, 0, 0)
    `LANE(8,  3, 3.6, 1.2,  9.8, en10, 10, rs12, 12, 0, 0)
    `LANE(9,  3, 3.6, 1.2, 14.8, en10, 10, rs12, 12, 0, 0)
    `LANE(10, 3, 3.6, 1.2, 24.8, en10, 10, rs12, 12, 0, 0)
    // +-80 ps (0.96 ns at T = 10) variants of 7..10 strapped with the NOMINAL lane's K: their checkers take the nominal L
    `define SWV(id, nom, XL_) \
      wire [W-1:0] o_``id; wire [2:0] k_``id = c_``nom.K[2:0]; \
      chk #(.W(W), .NF(3), .LAG(7.2 + XL_), .EXPF(0)) c_``id (ckd, ed, o_``id, f[id], c2_``id, e[id], c[id]); \
      wire [W-1:0] d1_``id, d2_``id; wire e1_``id, e2_``id, c1_``id, c2_``id, b0e_``id, b0c_``id, b1e_``id, b1c_``id; wire [W-1:0] b0_``id, b1_``id; \
      hbfd_lh0_136_EW s0_``id (.ck(cks), .en(en10), .a(src), .b(b0_``id), .eb(b0e_``id), .ck_o(b0c_``id)); \
      hop #(W, 3.6, 1.2) h1_``id (b0_``id, b0e_``id, b0c_``id, d1_``id, e1_``id, c1_``id); \
      hbfd_lh_136_EW s1_``id (.ckf(c1_``id), .ea(e1_``id), .a(d1_``id), .b(b1_``id), .eb(b1e_``id), .ck_o(b1c_``id)); \
      hop #(W, 3.6 + XL_, 1.2 + XL_) h2_``id (b1_``id, b1e_``id, b1c_``id, d2_``id, e2_``id, c2_``id); \
      hbfd_land_136_EW l_``id (.ckf(c2_``id), .ea(e2_``id), .a(d2_``id), .ck(ckd), .rs(rs12), .k0(k_``id[0]), .k1(k_``id[1]), .k2(k_``id[2]), .b(o_``id), .fault(f[id]));
    `SWV(11, 7,  3.84)  `SWV(12, 7,  5.76)
    `SWV(13, 8,  8.84)  `SWV(14, 8,  10.76)
    `SWV(15, 9,  13.84) `SWV(16, 9,  15.76)
    `SWV(17, 10, 23.84) `SWV(18, 10, 25.76)
    // ---------------------------------------------------------------- (c) fork trees
    // tree 1: s0 hop0 -> s1 lh_f2 -> br0: s2a lh -> landA (NF 4) ; br1: s2b lh_f3 -> br0 landB (NF 4), br1 s3 lh -> landC (NF 5),
    //         br2 s3d lh -> s4d lh (+XL 6.0 on its last hop) -> landD (NF 6)
    wire [W-1:0] t_b0; wire t_e0, t_c0;
    hbfd_lh0_136_EW t_s0 (.ck(cks), .en(en10), .a(src), .b(t_b0), .eb(t_e0), .ck_o(t_c0));
    wire [W-1:0] t_a1; wire t_ea1, t_cf1; hop #(W, 3.6, 1.2) t_h1 (t_b0, t_e0, t_c0, t_a1, t_ea1, t_cf1);
    wire [2*W-1:0] t_b1; wire [1:0] t_e1, t_c1;
    hbfd_lh_136_EW_f2 t_s1 (.ckf(t_cf1), .ea(t_ea1), .a(t_a1), .b(t_b1), .eb(t_e1), .ck_o(t_c1));
    // br0
    wire [W-1:0] t_a2a; wire t_ea2a, t_cf2a; hop #(W, 3.2, 1.0) t_h2a (t_b1[0 +: W], t_e1[0], t_c1[0], t_a2a, t_ea2a, t_cf2a);
    wire [W-1:0] t_b2a; wire t_e2a, t_c2a; hbfd_lh_136_EW t_s2a (.ckf(t_cf2a), .ea(t_ea2a), .a(t_a2a), .b(t_b2a), .eb(t_e2a), .ck_o(t_c2a));
    wire [W-1:0] t_aA; wire t_eaA, t_cfA; hop #(W, 3.6, 1.2) t_hA (t_b2a, t_e2a, t_c2a, t_aA, t_eaA, t_cfA);
    wire [W-1:0] o_19; chk #(.W(W), .NF(4), .LAG(3.6 + 3.2 + 3.6)) c_19 (ckd, ed, o_19, f[19], t_cfA, e[19], c[19]);
    hbfd_land_136_EW t_lA (.ckf(t_cfA), .ea(t_eaA), .a(t_aA), .ck(ckd), .rs(rs12), .k0(c_19.K[0]), .k1(c_19.K[1]), .k2(c_19.K[2]), .b(o_19), .fault(f[19]));
    // br1 -> f3
    wire [W-1:0] t_a2b; wire t_ea2b, t_cf2b; hop #(W, 4.0, 1.4) t_h2b (t_b1[W +: W], t_e1[1], t_c1[1], t_a2b, t_ea2b, t_cf2b);
    wire [3*W-1:0] t_b2b; wire [2:0] t_e2b, t_c2b;
    hbfd_lh_136_EW_f3 t_s2b (.ckf(t_cf2b), .ea(t_ea2b), .a(t_a2b), .b(t_b2b), .eb(t_e2b), .ck_o(t_c2b));
    wire [W-1:0] t_aB; wire t_eaB, t_cfB; hop #(W, 2.8, 0.8) t_hB (t_b2b[0 +: W], t_e2b[0], t_c2b[0], t_aB, t_eaB, t_cfB);
    wire [W-1:0] o_20; chk #(.W(W), .NF(4), .LAG(3.6 + 4.0 + 2.8)) c_20 (ckd, ed, o_20, f[20], t_cfB, e[20], c[20]);
    hbfd_land_136_EW t_lB (.ckf(t_cfB), .ea(t_eaB), .a(t_aB), .ck(ckd), .rs(rs12), .k0(c_20.K[0]), .k1(c_20.K[1]), .k2(c_20.K[2]), .b(o_20), .fault(f[20]));
    wire [W-1:0] t_a3; wire t_ea3, t_cf3; hop #(W, 3.6, 1.2) t_h3 (t_b2b[W +: W], t_e2b[1], t_c2b[1], t_a3, t_ea3, t_cf3);
    wire [W-1:0] t_b3; wire t_e3, t_c3; hbfd_lh_136_EW t_s3 (.ckf(t_cf3), .ea(t_ea3), .a(t_a3), .b(t_b3), .eb(t_e3), .ck_o(t_c3));
    wire [W-1:0] t_aC; wire t_eaC, t_cfC; hop #(W, 3.6, 1.2) t_hC (t_b3, t_e3, t_c3, t_aC, t_eaC, t_cfC);
    wire [W-1:0] o_21; chk #(.W(W), .NF(5), .LAG(3.6 + 4.0 + 3.6 + 3.6)) c_21 (ckd, ed, o_21, f[21], t_cfC, e[21], c[21]);
    hbfd_land_136_EW t_lC (.ckf(t_cfC), .ea(t_eaC), .a(t_aC), .ck(ckd), .rs(rs12), .k0(c_21.K[0]), .k1(c_21.K[1]), .k2(c_21.K[2]), .b(o_21), .fault(f[21]));
    wire [W-1:0] t_a3d; wire t_ea3d, t_cf3d; hop #(W, 3.0, 1.0) t_h3d (t_b2b[2*W +: W], t_e2b[2], t_c2b[2], t_a3d, t_ea3d, t_cf3d);
    wire [W-1:0] t_b3d; wire t_e3d, t_c3d; hbfd_lh_136_EW t_s3d (.ckf(t_cf3d), .ea(t_ea3d), .a(t_a3d), .b(t_b3d), .eb(t_e3d), .ck_o(t_c3d));
    wire [W-1:0] t_a4d; wire t_ea4d, t_cf4d; hop #(W, 3.6, 1.2) t_h4d (t_b3d, t_e3d, t_c3d, t_a4d, t_ea4d, t_cf4d);
    wire [W-1:0] t_b4d; wire t_e4d, t_c4d; hbfd_lh_136_EW t_s4d (.ckf(t_cf4d), .ea(t_ea4d), .a(t_a4d), .b(t_b4d), .eb(t_e4d), .ck_o(t_c4d));
    wire [W-1:0] t_aD; wire t_eaD, t_cfD; hop #(W, 9.6, 7.2) t_hD (t_b4d, t_e4d, t_c4d, t_aD, t_eaD, t_cfD);
    wire [W-1:0] o_22; chk #(.W(W), .NF(6), .LAG(3.6 + 4.0 + 3.0 + 3.6 + 9.6)) c_22 (ckd, ed, o_22, f[22], t_cfD, e[22], c[22]);
    hbfd_land_136_EW t_lD (.ckf(t_cfD), .ea(t_eaD), .a(t_aD), .ck(ckd), .rs(rs12), .k0(c_22.K[0]), .k1(c_22.K[1]), .k2(c_22.K[2]), .b(o_22), .fault(f[22]));
    // tree 2: hop-0 fork lh0_f2 -> br0 landE (NF 2), br1 lh -> landF (NF 3)
    wire [2*W-1:0] u_b0; wire [1:0] u_e0, u_c0;
    hbfd_lh0_136_EW_f2 u_s0 (.ck(cks), .en(en10), .a(src), .b(u_b0), .eb(u_e0), .ck_o(u_c0));
    wire [W-1:0] u_aE; wire u_eaE, u_cfE; hop #(W, 3.4, 1.0) u_hE (u_b0[0 +: W], u_e0[0], u_c0[0], u_aE, u_eaE, u_cfE);
    wire [W-1:0] o_23; chk #(.W(W), .NF(2), .LAG(3.4)) c_23 (ckd, ed, o_23, f[23], u_cfE, e[23], c[23]);
    hbfd_land_136_EW u_lE (.ckf(u_cfE), .ea(u_eaE), .a(u_aE), .ck(ckd), .rs(rs12), .k0(c_23.K[0]), .k1(c_23.K[1]), .k2(c_23.K[2]), .b(o_23), .fault(f[23]));
    wire [W-1:0] u_a1; wire u_ea1, u_cf1; hop #(W, 3.6, 1.2) u_h1 (u_b0[W +: W], u_e0[1], u_c0[1], u_a1, u_ea1, u_cf1);
    wire [W-1:0] u_b1; wire u_e1, u_c1; hbfd_lh_136_EW u_s1 (.ckf(u_cf1), .ea(u_ea1), .a(u_a1), .b(u_b1), .eb(u_e1), .ck_o(u_c1));
    wire [W-1:0] u_aF; wire u_eaF, u_cfF; hop #(W, 3.6, 1.2) u_hF (u_b1, u_e1, u_c1, u_aF, u_eaF, u_cfF);
    wire [W-1:0] o_24; chk #(.W(W), .NF(3), .LAG(7.2)) c_24 (ckd, ed, o_24, f[24], u_cfF, e[24], c[24]);
    hbfd_land_136_EW u_lF (.ckf(u_cfF), .ea(u_eaF), .a(u_aF), .ck(ckd), .rs(rs12), .k0(c_24.K[0]), .k1(c_24.K[1]), .k2(c_24.K[2]), .b(o_24), .fault(f[24]));
    // ---------------------------------------------------------------- (d) slip: lane 2's geometry strapped K + D (= +4 mod 8)
    `LANE(25, 5, 3.6, 1.2, 0.0, en10, 10, rs12, 12, 4, 1)
    `LANE(26, 3, 3.6, 1.2, 0.0, en10, 10, rs12, 12, 4, 1)
    // (e) unwritten-slot lane: late source (G 40), read 1.2 T after the write (x = 3.8, L = 5), so the read of epoch -1
    //     (slot 3, not yet written) falls 0.2 T AFTER the first ring write:
    //     with power-on garbage in the ring an every-slot-valid landing (mutant vld) delivers garbage instead of a 0 bubble
    `LANE(27, 3, 3.6, 1.2, 12.8, en40, 40, rs9, 9, 0, 0)
    genvar z; generate for (z = 28; z < NL; z = z + 1) begin : g_pad assign f[z] = 1'b0; initial begin e[z] = 0; c[z] = 0; end end endgenerate
    initial begin
        #12000;
        begin : sum
            integer i, te, tc, tf, ts;
            te = 0; tc = 0; tf = 0; ts = 0;
            for (i = 0; i < 28; i = i + 1) begin
                te = te + e[i]; tc = tc + c[i];
                if (i == 25 || i == 26) begin if (f[i] !== 1'b1) begin ts = ts + 1; $display("LANE_SLIP_UNDETECTED lane %0d", i); end end
                else if (f[i] !== 1'b0) begin tf = tf + 1; $display("LANE_FAULT lane %0d", i); end
            end
            $display("LANE_SWEEP L nominal/-80/+80: %0d/%0d/%0d %0d/%0d/%0d %0d/%0d/%0d %0d/%0d/%0d", c_7.L, c_11.L, c_12.L,
                     c_8.L, c_13.L, c_14.L, c_9.L, c_15.L, c_16.L, c_10.L, c_17.L, c_18.L);
            $display("LANE_BENCH %s %0d errors in %0d checks (faults %0d, slips undetected %0d)",
                     (te || tf || ts || tc < 20000) ? "FAIL" : "PASS", te + tf + ts, tc, tf, ts);
        end
        $finish;
    end
endmodule
EOT
# the +-80 variants' checkers must use the nominal lane's L: patch their L at time 0+
python3 - "$O/tb.sv" <<'PY'
import sys, re
p = sys.argv[1]; t = open(p).read()
pairs = {11: 7, 12: 7, 13: 8, 14: 8, 15: 9, 16: 9, 17: 10, 18: 10}
t = t.replace('    initial begin\n        #12000;', '    initial begin\n        #0.1;\n' + ''.join(f'        c_{a}.L = c_{b}.L; c_{a}.K = c_{b}.K;\n' for a, b in pairs.items()) + '        #12000;')
open(p, 'w').write(t)
PY
sed -i "s/_136_EW/_${W}_EW/g; s/localparam integer W = 136;/localparam integer W = ${W};/" "$O/tb.sv"
verilator --binary --timing -Wno-fatal -Wno-WIDTH -Wno-MULTIDRIVEN -Wno-COMBDLY -Wno-LATCH -Wno-INITIALDLY -Wno-UNOPTFLAT --top-module tb $DEF \
  -Mdir "$O/obj" -o tb "$O/tb.sv" rtl/hbm_accel/die_glue/hbfd_lane_masters.sv rtl/hbm_accel/die_glue/ot_hbm_lane.sv \
  rtl/qwen_split/qfd_fwd_lane.sv rtl/hdc/ot_hdc_cg.sv > "$O/build.log" 2>&1 || { echo BUILD_FAILED; tail -30 "$O/build.log"; exit 2; }
"$O/obj/tb" > "$O/bench.log" 2>&1
grep -E 'LANE_BENCH|LANE_SWEEP|LANE_FAULT|LANE_SLIP|LANE tb|LANE_MISMATCH|LANE_PHASE' "$O/bench.log" | grep -v LANE_BENCH | head -40
grep -E 'LANE_BENCH' "$O/bench.log"
grep -q 'LANE_BENCH PASS' "$O/bench.log"
